<script lang="ts">
  import { api } from '$lib/api';
  let mode = $state<'camera' | 'recorder' | 'assignment'>('camera');
  let message = $state(''); let error = $state(''); let busy = $state(false); let reviewing = $state(false);
  let assetId = $state(''); let physicalLocation = $state(''); let channelCapacity = $state(''); let cameraId = $state(''); let channelId = $state('');
  let assets = $state<{ id: string; name: string; assetTag: string | null }[]>([]); let cameras = $state<{ id: string; asset: { name: string }; assignments: { id: string; updatedAt: string; validTo: string | null; channel: { channelNumber: number } }[] }[]>([]); let channels = $state<{ id: string; channelNumber: number; enabled: boolean; assignments: unknown[]; recorder: { asset: { name: string } } }[]>([]); let endDate = $state(''); let endReason = $state('');
  import { onMount } from 'svelte';
  onMount(async () => { try { assets = await api.get<typeof assets>('/api/assets'); const cameraResponse = await api.get<{ items: typeof cameras }>('/api/cctv/cameras'); cameras = cameraResponse.items; const recorderResponse = await api.get<{ items: { channels: typeof channels }[] }>('/api/cctv/recorders?available=true'); channels = recorderResponse.items.flatMap((recorder) => recorder.channels).filter((channel) => channel.enabled && channel.assignments.length === 0); } catch { /* permission and empty states are rendered by the form */ } });
  async function submit() { if (!reviewing) { reviewing = true; return; } busy = true; message = ''; error = ''; try { const body = mode === 'camera' ? { assetId, physicalLocation } : mode === 'recorder' ? { assetId, physicalLocation, channelCapacity: Number(channelCapacity), channels: Array.from({ length: Number(channelCapacity) || 0 }, (_, index) => ({ channelNumber: index + 1, enabled: true })) } : { cameraId, channelId, validFrom: new Date().toISOString() }; await api.post(`/api/cctv/${mode === 'camera' ? 'cameras' : mode === 'recorder' ? 'recorders' : 'channel-assignments'}`, body, { headers: { 'Idempotency-Key': crypto.randomUUID() } }); message = mode === 'assignment' ? 'Assignment confirmed and recorded.' : 'CCTV metadata confirmed and recorded.'; reviewing = false; } catch (e) { error = (e as Error).message; } finally { busy = false; } }
  async function endCurrent() { const current = cameras.find((camera) => camera.id === cameraId)?.assignments.find((assignment) => !assignment.validTo); if (!current || !endDate) return; busy = true; error = ''; try { await api.post(`/api/cctv/channel-assignments/${current.id}/end`, { validTo: new Date(endDate).toISOString(), reason: endReason, expectedUpdatedAt: current.updatedAt }); message = 'Current assignment ended. You can now assign a replacement channel.'; await new Promise((resolve) => setTimeout(resolve, 0)); } catch (e) { error = (e as Error).message; } finally { busy = false; } }
</script>
<svelte:head><title>CCTV intake — Oracle Inventory</title></svelte:head>
<div class="page"><header><h1>CCTV / NVR manual intake</h1><p>Record hardware metadata only. Do not enter passwords, stream URLs, or credentials.</p></header><nav aria-label="Intake type" class="tabs">{#each [['camera','Camera'],['recorder','NVR / recorder'],['assignment','Assign channel']] as item}<button class:active={mode === item[0]} onclick={() => { mode = item[0] as typeof mode; message = ''; error = ''; reviewing = false; }}>{item[1]}</button>{/each}</nav><section class="panel" aria-labelledby="form-heading"><h2 id="form-heading">{reviewing ? 'Review and confirm' : mode === 'camera' ? 'Camera profile' : mode === 'recorder' ? 'Recorder profile' : 'Channel assignment'}</h2>{#if reviewing}<dl><dt>Type</dt><dd>{mode}</dd><dt>Asset / camera</dt><dd>{assetId || cameraId}</dd><dt>Location / channel</dt><dd>{physicalLocation || channelId}</dd></dl><p class="hint">Review the summary, then explicitly confirm. Conflicts and stale assignments will be rejected by the server.</p>{:else if mode !== 'assignment'}<label>Asset<select bind:value={assetId} required><option value="">Select an asset</option>{#each assets as asset}<option value={asset.id}>{asset.name} · {asset.assetTag ?? 'No tag'}</option>{/each}</select></label><p id="asset-help" class="hint">Only assets in your authorized branch can be saved. Category is checked by the server.</p><label>Physical location<input bind:value={physicalLocation} required /></label>{#if mode === 'recorder'}<label>Channel capacity<input type="number" min="1" bind:value={channelCapacity} required /></label>{/if}{:else}<label>Camera<select bind:value={cameraId} required><option value="">Select a camera</option>{#each cameras as camera}<option value={camera.id}>{camera.asset.name}</option>{/each}</select></label><label>Recorder channel<select bind:value={channelId} required><option value="">Select an available channel</option>{#each channels as channel}<option value={channel.id}>Channel {channel.channelNumber} · {channel.recorder.asset.name}</option>{/each}</select></label>{#if cameras.find((camera) => camera.id === cameraId)?.assignments.find((assignment) => !assignment.validTo)}<fieldset><legend>Current assignment</legend><label>End date<input type="datetime-local" bind:value={endDate} required /></label><label>Reason<textarea bind:value={endReason} required></textarea></label><button class="secondary" onclick={endCurrent} disabled={busy}>End current assignment for reassignment</button></fieldset>{/if}<p class="hint">Only enabled, currently available channels are offered. Conflicts and stale writes are rejected; history is preserved.</p>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}{#if message}<p class="success" role="status">{message}</p>{/if}<button class="primary" onclick={submit} disabled={busy}>{busy ? 'Saving…' : reviewing ? 'Confirm and save' : 'Review'}</button>{#if reviewing}<button class="secondary" onclick={() => reviewing = false} disabled={busy}>Back to edit</button>{/if}</section><section class="panel states"><h2>Review states</h2><ul><li>Unassigned cameras remain visible until a channel is selected.</li><li>Conflicts and no-available-channel responses are shown without overwriting history.</li><li>Reassignment requires ending the current assignment before creating the next one; stale saves are rejected.</li></ul></section></div>
<style>.page{max-width:900px;margin:0 auto;padding:32px}header h1{margin:0}header p,.hint{color:var(--muted-foreground,#71717a)}.tabs{display:flex;gap:8px;margin:24px 0;flex-wrap:wrap}.tabs button,.primary{padding:9px 14px;border:1px solid var(--border,#e4e4e7);border-radius:8px;background:var(--card,#fff);cursor:pointer}.tabs .active,.primary{background:#18181b;color:#fff}.panel{border:1px solid var(--border,#e4e4e7);border-radius:10px;padding:20px;margin-bottom:16px}label{display:block;font-weight:600;margin:14px 0}input{display:block;width:100%;box-sizing:border-box;padding:9px;margin-top:6px;border:1px solid var(--border,#e4e4e7);border-radius:7px;font:inherit}.error{color:#b91c1c}.success{color:#166534}.states li{margin:8px 0}</style>
